long long gcd(long long a, long long b) {
    while (b) { a %= b; swap(a, b); }
    return a;
}
long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b;
}
// extended: returns gcd, sets x,y with a*x + b*y = gcd
long long egcd(long long a, long long b, long long& x, long long& y){
    if (!b){ x=1; y=0; return a; }
    long long x1,y1, g = egcd(b, a%b, x1, y1);
    x = y1; y = x1 - (a/b)*y1; return g;
}

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a // gcd(a, b) * b

def egcd(a, b):                # returns (g, x, y) with a*x + b*y = g
    if b == 0:
        return (a, 1, 0)
    g, x1, y1 = egcd(b, a % b)
    return (g, y1, x1 - (a // b) * y1)

class Solution {
public:
    string gcdOfStrings(string a, string b) {
        if (a + b != b + a) return "";
        int g = __gcd((int)a.size(), (int)b.size());
        return a.substr(0, g);
    }
};

from math import gcd
class Solution:
    def gcdOfStrings(self, a: str, b: str) -> str:
        if a + b != b + a:
            return ""
        return a[:gcd(len(a), len(b))]

class Solution {
public:
    bool canMeasureWater(int a, int b, int target) {
        if (target > a + b) return false;
        if (a == 0 || b == 0) return target == 0 || target == a + b;
        return target % __gcd(a, b) == 0;
    }
};

