from math import gcd
class Solution:
    def smallestMultiple(self, n: int) -> int:
        acc = 1
        for i in range(2, n + 1):
            acc = acc // gcd(acc, i) * i
        return acc

class Solution {
    long long ext(long long a, long long b, long long& x, long long& y) {
        if (!b) { x = 1; y = 0; return a; }
        long long x1, y1, g = ext(b, a % b, x1, y1);
        x = y1; y = x1 - (a / b) * y1;
        return g;
    }
public:
    long long modInverse(long long a, long long m) {
        long long x, y, g = ext(a, m, x, y);
        if (g != 1) return -1;       // no inverse
        return (x % m + m) % m;
    }
};

class Solution:
    def modInverse(self, a: int, m: int) -> int:
        def ext(a, b):
            if b == 0:
                return a, 1, 0
            g, x1, y1 = ext(b, a % b)
            return g, y1, x1 - (a // b) * y1
        g, x, _ = ext(a, m)
        if g != 1:
            return -1
        return x % m

class Solution {
public:
    long long subarrayGCD(vector<int>& nums, int k) {
        long long ans = 0;
        vector<pair<int,int>> prev;   // (gcd, count)
        for (int x : nums) {
            vector<pair<int,int>> cur;
            cur.push_back({x, 1});
            for (auto& [g, c] : prev) {
                int ng = __gcd(g, x);
                if (!cur.empty() && cur.back().first == ng) cur.back().second += c;
                else cur.push_back({ng, c});
            }
            prev = cur;
            for (auto& [g, c] : prev) if (g == k) ans += c;
        }
        return ans;
    }
};

from math import gcd
class Solution:
    def subarrayGCD(self, nums: list[int], k: int) -> int:
        ans = 0
        prev = []   # list of [gcd, count]
        for x in nums:
            cur = [[x, 1]]
            for g, c in prev:
                ng = gcd(g, x)
                if cur[-1][0] == ng:
                    cur[-1][1] += c
                else:
                    cur.append([ng, c])
            prev = cur
            ans += sum(c for g, c in prev if g == k)
        return ans
